begin;
alter table public.contact_history add column follow_up_status text not null default 'scheduled' check(follow_up_status in ('scheduled','completed','cancelled'));
create index adjustment_payment_lookup on public.financial_adjustments(payment_id);
create index allocation_history_payment_lookup on public.allocation_history(payment_id,created_at);
create index assessment_history_lookup on public.assessment_history(assessment_id,created_at);
drop function public.search_members(text,text,text,integer,integer);
create function public.search_members(p_query text default '',p_status text default '',p_country text default '',p_offset integer default 0,p_limit integer default 20,p_sort text default 'full_name',p_desc boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin perform public.require_permission('directory.read');if p_offset<0 or p_limit not between 1 and 100 or length(p_query)>180 or p_sort not in ('full_name','member_no','city','occupation','membership_status','skills') then raise exception 'Invalid search bounds';end if;
with matches as (select m.* from public.members m where (p_status='' or membership_status=p_status) and (p_country='' or country=p_country) and (p_query='' or strpos(lower(concat_ws(' ',full_name,member_no,phone_original,phone_normalized,city,region,country,occupation,joined_year,array_to_string(skills,' '))),lower(p_query))>0)),ordered as (select m.*,case p_sort when 'member_no' then member_no when 'city' then city when 'occupation' then occupation when 'membership_status' then membership_status when 'skills' then array_to_string(skills,' ') else full_name end sort_value from matches m)
select jsonb_build_object('count',(select count(*) from matches),'rows',(select coalesce(jsonb_agg(to_jsonb(t)-array['details','internal_remarks','name_normalized','archive_reason','sort_value']),'[]') from (select * from ordered order by case when not p_desc then lower(sort_value) end asc,case when p_desc then lower(sort_value) end desc,id limit p_limit offset p_offset)t)) into result;return result;end;$$;
create function public.search_payments(p_query text default '',p_status text default '',p_method text default '',p_credit boolean default false,p_offset integer default 0,p_limit integer default 20,p_sort text default 'reference',p_desc boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin perform public.require_permission('finance.read');if p_offset<0 or p_limit not between 1 and 100 or length(p_query)>180 or p_sort not in ('member','reference','payment_date','amount_kobo','credit','status') then raise exception 'Invalid search bounds';end if;
with base as(select p.*,m.full_name member_name,public.net_payment(p.id) net_kobo,case when p.status='confirmed' then public.net_payment(p.id)-coalesce((select sum(a.amount_kobo) from public.payment_allocations a where a.payment_id=p.id),0) else 0 end credit_kobo from public.payments p join public.members m on m.id=p.member_id where (p_status='' or p.status=p_status) and (p_method='' or method=p_method) and (p_query='' or strpos(lower(concat_ws(' ',m.full_name,m.member_no,p.reference,p.external_reference)),lower(p_query))>0)),matches as(select * from base where not p_credit or credit_kobo>0),ordered as(select b.*,case p_sort when 'member' then member_name when 'payment_date' then payment_date::text when 'status' then status else reference end sort_text,case p_sort when 'amount_kobo' then amount_kobo when 'credit' then credit_kobo end sort_number from matches b)
select jsonb_build_object('count',(select count(*) from matches),'rows',(select coalesce(jsonb_agg(to_jsonb(t)-array['sort_text','sort_number']),'[]') from(select * from ordered order by case when not p_desc then sort_number end asc nulls last,case when p_desc then sort_number end desc nulls last,case when not p_desc then lower(sort_text) end asc,case when p_desc then lower(sort_text) end desc,id limit p_limit offset p_offset)t)) into result;return result;end;$$;
create function public.overview_metrics(p_from date,p_to date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d jsonb;begin perform public.require_permission('directory.read');if p_from>p_to or p_to-p_from>366 then raise exception 'Choose an overview range up to 12 months';end if;
 d=jsonb_build_object('member_count',(select count(*) from public.members where archived_at is null),'active_count',(select count(*) from public.members where archived_at is null and membership_status='active'),'event_count',(select count(*) from public.events));
 if public.has_permission('finance.read') then d=d||jsonb_build_object('cash',(select coalesce(sum(public.net_payment(id)),0) from public.payments where payment_date between p_from and p_to),'outstanding',(select coalesce(sum(greatest(0,a.expected_kobo-a.waiver_kobo-coalesce((select sum(x.amount_kobo) from public.payment_allocations x join public.payments p on p.id=x.payment_id where p.status='confirmed' and x.member_id=a.member_id and x.collection_id=a.collection_id),0))),0) from public.member_assessments a where superseded_by is null),'credit',(select coalesce(sum(public.net_payment(p.id)-coalesce((select sum(a.amount_kobo) from public.payment_allocations a where a.payment_id=p.id),0)),0) from public.payments p where p.status='confirmed'),'credit_count',(select count(*) from public.payments p where p.status='confirmed' and public.net_payment(p.id)>coalesce((select sum(a.amount_kobo) from public.payment_allocations a where a.payment_id=p.id),0)),'pending_payments',(select count(*) from public.payments where status='pending'),'chart',(select coalesce(jsonb_agg(jsonb_build_object('key',to_char(month,'YYYY-MM'),'value',coalesce((select sum(public.net_payment(p.id)) from public.payments p where p.payment_date between p_from and p_to and to_char(p.payment_date,'YYYY-MM')=to_char(month,'YYYY-MM')),0)) order by month),'[]') from generate_series(date_trunc('month',p_from::timestamp),date_trunc('month',p_to::timestamp),interval '1 month') month));end if;return d;
end;$$;

-- Page-scoped data delivery. Directory selectors contain safe summaries; detailed private
-- profiles are returned only for the selected member. Finance reports intentionally request
-- their full authorised ledger; the ordinary overview and lists use aggregate/paged RPCs.
create function public.workspace_data(p_area text,p_target uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d jsonb;pay_ids uuid[];mid uuid;begin perform public.require_permission('directory.read');
 if p_area not in ('login','overview','members','registrations','monthly','special','payments','expenses','events','welfare','contacts','documents','reports','branding','accounts','audit') then raise exception 'Unknown workspace area';end if;
 d=jsonb_build_object('branding',(select to_jsonb(b) from public.branding b),'members',(select coalesce(jsonb_agg(case when m.id=p_target and p_area='members' and public.has_permission('members.write') then to_jsonb(m) else (to_jsonb(m)-array['details','internal_remarks','archive_reason','name_normalized'])||jsonb_build_object('details',case when m.id=p_target and p_area='members' then jsonb_build_object('qualification',m.details->'qualification','qualification_other',m.details->'qualification_other','course',m.details->'course','institution',m.details->'institution','occupation_other',m.details->'occupation_other','business_name',m.details->'business_name','business_sector',m.details->'business_sector','business_description',m.details->'business_description','whatsapp',m.details->'whatsapp','whatsapp_normalized',m.details->'whatsapp_normalized','socials',m.details->'socials') else '{}'::jsonb end) end),'[]') from public.members m),'events',(select coalesce(jsonb_agg(to_jsonb(e)),'[]') from public.events e),'attendance',case when p_area in ('events','members','reports') then (select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.event_attendance a where p_area='reports' or p_area='events' and a.event_id=p_target or p_area='members' and a.member_id=p_target) else '[]'::jsonb end);
 d=d||jsonb_build_object('submissions',case when public.has_permission('registrations.review') and p_area in ('registrations','reports') then (select coalesce(jsonb_agg(to_jsonb(s)),'[]') from public.membership_submissions s) when public.has_permission('registrations.review') and p_area in ('overview','login') then (select coalesce(jsonb_agg(jsonb_build_object('id',id,'review_status',review_status)),'[]') from public.membership_submissions where review_status='pending') else '[]'::jsonb end,'contacts',case when public.has_permission('members.write') and p_area in ('overview','contacts','members','reports') then (select coalesce(jsonb_agg(to_jsonb(t)),'[]') from public.contact_history t where p_area<>'members' or member_id=p_target) else '[]'::jsonb end);
 if public.has_permission('finance.read') then
 if p_area='payments' then select member_id into mid from public.payments where id=p_target;end if;
 select coalesce(array_agg(p.id),'{}') into pay_ids from public.payments p where p_area='reports' or p_area='payments' and p.id=p_target or p_area='members' and p.member_id=p_target or p_area in ('monthly','special') and exists(select 1 from public.payment_allocations a where a.payment_id=p.id and a.collection_id=p_target);
 d=d||jsonb_build_object('collections',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from public.contribution_collections c),'payments',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.payments p where p.id=any(pay_ids)),'allocations',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.payment_allocations a where a.payment_id=any(pay_ids)),'adjustments',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.financial_adjustments a where a.payment_id=any(pay_ids)),'assessments',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.member_assessments a where superseded_by is null and (p_area='reports' or p_area='members' and member_id=p_target or p_area='payments' and member_id=mid or p_area in ('monthly','special') and collection_id=p_target)),'expenses',case when p_area in ('monthly','special','expenses','welfare','reports') then (select coalesce(jsonb_agg(to_jsonb(e)),'[]') from public.expenses e where p_area not in ('monthly','special') or collection_id=p_target) else '[]'::jsonb end);
 else d=d||jsonb_build_object('collections','[]'::jsonb,'payments','[]'::jsonb,'allocations','[]'::jsonb,'adjustments','[]'::jsonb,'assessments','[]'::jsonb,'expenses','[]'::jsonb);end if;
 d=d||jsonb_build_object('welfare',case when public.has_permission('welfare.read') and p_area in ('welfare','reports','documents','overview') then (select coalesce(jsonb_agg(to_jsonb(w)),'[]') from public.welfare_cases w where assigned_to=auth.uid()) else '[]'::jsonb end,'documents',case when p_area in ('documents','members','payments','monthly','special','expenses','welfare','events') then (select coalesce(jsonb_agg(to_jsonb(f)),'[]') from public.documents f where public.can_access_document(f.scope,f.target_id) and (p_area='documents' or p_area='welfare' and f.scope='welfare' or p_area='members' and f.scope='member' and target_id=p_target or p_area='payments' and f.scope='payment' and target_id=p_target or p_area in ('monthly','special') and (f.scope='collection' and target_id=p_target or f.scope='expense' and exists(select 1 from public.expenses e where e.id=target_id and collection_id=p_target)) or p_area='expenses' and f.scope='expense' or p_area='events' and f.scope='collection' and exists(select 1 from public.events e where e.id=p_target and e.collection_id=f.target_id))) else '[]'::jsonb end,'audit',case when p_area='audit' and public.has_permission('audit.read') then (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc),'[]') from public.audit_events a) else '[]'::jsonb end,'settings',case when p_area='branding' and public.has_permission('settings.write') then (select to_jsonb(s)-'mfa_required' from public.private_settings s) else '{}'::jsonb end,'officers',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'display_name',a.display_name,'active',a.active,'welfare_eligible',public.has_permission_for(a.id,'welfare.read') and public.has_permission_for(a.id,'welfare.write'))),'[]') from public.executive_accounts a));
 if p_area='accounts' and public.has_permission('accounts.write') then d=d||jsonb_build_object('accounts',(select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('roles',(select coalesce(jsonb_agg(role_code),'[]') from public.role_assignments where executive_id=a.id and revoked_at is null and starts_at<=now() and (expires_at is null or expires_at>now())),'extra_permissions',(select coalesce(jsonb_agg(permission),'[]') from public.explicit_permissions where executive_id=a.id),'denied_permissions',(select coalesce(jsonb_agg(permission),'[]') from public.permission_denials where executive_id=a.id),'role_history',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]') from public.role_assignments r where executive_id=a.id))),'[]') from public.executive_accounts a));else d=d||jsonb_build_object('accounts',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'display_name',a.display_name,'active',a.active)),'[]') from public.executive_accounts a where id=auth.uid()));end if;return d;
end;$$;
create function public.member_finance_context(p_member uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform public.require_permission('finance.read');return (select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.member_assessments a where member_id=p_member and superseded_by is null);end;$$;
revoke execute on function public.search_members(text,text,text,integer,integer,text,boolean),public.search_payments(text,text,text,boolean,integer,integer,text,boolean),public.overview_metrics(date,date),public.workspace_data(text,uuid),public.member_finance_context(uuid) from public,anon;
grant execute on function public.search_members(text,text,text,integer,integer,text,boolean),public.search_payments(text,text,text,boolean,integer,integer,text,boolean),public.overview_metrics(date,date),public.workspace_data(text,uuid),public.member_finance_context(uuid) to authenticated;
commit;
